function ns.GetEnchantMetadata(enchantID)
    if not enchantID or enchantID == 0 then return nil end
    local meta = ns.Data.EnchantsMetadata and ns.Data.EnchantsMetadata[enchantID]
    if meta then return meta end

    local spellName, _, spellIcon
    if GetSpellInfo then
        local ok, sName, _, sIcon = pcall(GetSpellInfo, enchantID)
        if ok and sName then spellName, spellIcon = sName, sIcon end
    end

    return {
        name = spellName or ("Encantamiento #" .. enchantID),
        effect = "Mejora mágica de estadísticas",
        slot = "Equipo",
        quality = 2,
        type = "Encantamiento",
        source = "Mundo Clásico",
        materials = "Materiales de encantamiento",
        icon = spellIcon or "Interface\\Icons\\spell_holy_magicalsentry",
        desc = "Encantamiento óptimo para WoW Classic.",
    }
end

function ns.GetClassDefaultEnchantSpec(playerClass)
    playerClass = (playerClass or select(2, UnitClass("player")) or "WARRIOR"):upper()
    local map = {
        ["WARRIOR"] = "fury_warrior",
        ["ROGUE"]   = "rogue_combat",
        ["HUNTER"]  = "hunter_mark",
        ["MAGE"]    = "mage_frost",
        ["WARLOCK"] = "warlock_ruin",
        ["PRIEST"]  = "priest_holy",
        ["DRUID"]   = "feral_cat",
        ["PALADIN"] = "paladin_holy",
        ["SHAMAN"]  = "shaman_resto",
    }
    return map[playerClass] or "fury_warrior"
end

function ns.GetEnchantSpecsForClass(playerClass)
    playerClass = (playerClass or select(2, UnitClass("player")) or "WARRIOR"):upper()
    local map = {
        ["WARRIOR"] = { "fury_warrior", "protection_warrior" },
        ["ROGUE"]   = { "rogue_combat" },
        ["HUNTER"]  = { "hunter_mark" },
        ["MAGE"]    = { "mage_frost" },
        ["WARLOCK"] = { "warlock_ruin" },
        ["PRIEST"]  = { "priest_holy", "priest_shadow" },
        ["DRUID"]   = { "feral_cat", "feral_bear", "druid_resto" },
        ["PALADIN"] = { "paladin_holy", "protection_paladin" },
        ["SHAMAN"]  = { "shaman_resto" },
    }
    return map[playerClass] or { "fury_warrior", "protection_warrior" }
end

function ns.GetAllEnchantSpecs()
    return {
        "fury_warrior",
        "protection_warrior",
        "rogue_combat",
        "feral_cat",
        "feral_bear",
        "druid_resto",
        "hunter_mark",
        "mage_frost",
        "warlock_ruin",
        "priest_holy",
        "priest_shadow",
        "paladin_holy",
        "protection_paladin",
        "shaman_resto",
    }
end

function ns.GetEnchantsForSpec(specKey, bracketKey)
    if not specKey or not ns.Data.EnchantsDatabase then return nil end
    if not bracketKey then
        local pLvl = UnitLevel("player") or 1
        bracketKey = ns.GetDefaultBiSBracket and ns.GetDefaultBiSBracket(pLvl) or "pre-raid"
    end

    if bracketKey == "1-14" then
        for catKey, catData in pairs(ns.Data.EnchantsDatabase) do
            if catData.specs then
                for _, s in ipairs(catData.specs) do
                    if s.key == specKey then
                        return {}, s, catData
                    end
                end
            end
        end
        return {}, { key = specKey, name = specKey }, ns.Data.EnchantsDatabase["MELEE_DPS"]
    end

    for catKey, catData in pairs(ns.Data.EnchantsDatabase) do
        if catData.specs then
            for _, s in ipairs(catData.specs) do
                if s.key == specKey then
                    local setObj = catData.sets and (catData.sets[bracketKey] or catData.sets["pre-raid"] or catData.sets["15-25"])
                    local set = setObj and setObj.enchants
                    return set, s, catData
                end
            end
        end
    end
    local defCat = ns.Data.EnchantsDatabase["MELEE_DPS"]
    local defSetObj = defCat and defCat.sets and (defCat.sets[bracketKey] or defCat.sets["pre-raid"] or defCat.sets["15-25"])
    return defSetObj and defSetObj.enchants, { key = "fury_warrior", name = "Guerrero Furia" }, defCat
end

-- =========================================================================
-- FUNCIONES AUXILIARES DE BIS
-- =========================================================================

--- Obtiene el tramo de nivel (bracket) recomendado según el nivel del jugador
function ns.GetDefaultBiSBracket(level)
    level = tonumber(level) or (UnitLevel and UnitLevel("player")) or 1
    if level < 15 then
        return "1-14"
    elseif level < 26 then
        return "15-25"
    elseif level < 41 then
        return "26-40"
    elseif level < 53 then
        return "41-52"
    elseif level < 60 then
        return "pre-raid"
    else
        return "raid-p1"
    end
end

--- Comprueba si el jugador tiene el objeto equipado o en sus bolsas
function ns.GetPlayerItemStatus(itemID)
    if not itemID or itemID == 0 then return false, false end

    -- 1. Escaneo seguro de ranuras equipadas (1 a 19)
    if GetInventoryItemID then
        for slot = 1, 19 do
            local ok, invID = pcall(GetInventoryItemID, "player", slot)
            if ok and invID == itemID then
                return true, false
            end
        end
    end

    -- 2. Escaneo seguro de bolsas del jugador (0 a NUM_BAG_SLOTS)
    local numBags = NUM_BAG_SLOTS or 4
    for bag = 0, numBags do
        local numSlots = 0
        if C_Container and C_Container.GetContainerNumSlots then
            numSlots = C_Container.GetContainerNumSlots(bag) or 0
        elseif GetContainerNumSlots then
            numSlots = GetContainerNumSlots(bag) or 0
        end

        for slot = 1, numSlots do
            local id
            if C_Container and C_Container.GetContainerItemID then
                id = C_Container.GetContainerItemID(bag, slot)
            elseif GetContainerItemID then
                id = GetContainerItemID(bag, slot)
            end

            if id == itemID then
                return false, true
            end
        end
    end

    return false, false
end

--- Obtiene los metadatos de obtención del objeto (Jefe, Zona, Drop, etc.)
function ns.GetBiSItemMetadata(itemID)
    if not itemID or itemID == 0 then return nil end
    local pre = ns.Data.BiSItems and ns.Data.BiSItems[itemID]
    if pre then return pre end

    local LE = LibStub and LibStub("LibEquippable-1.0", true)
    if LE and LE.GetItemWithID then
        local entry = LE:GetItemWithID(itemID)
        if entry and entry.source then
            return {
                name = entry.name or ("Objeto #" .. itemID),
                source = entry.source.SourceName or "Desconocido",
                type = entry.source.SourceType or "Kill",
                zone = entry.source.Zone or "Azeroth",
                drop = (entry.source.DropChance and entry.source.DropChance ~= "0") and (entry.source.DropChance .. "%") or "Común"
            }
        end
    end

    local itemName
    if C_Item and C_Item.GetItemInfo then
        local ok, n = pcall(C_Item.GetItemInfo, itemID)
        if ok and n then itemName = n end
    end
    if not itemName and _G.GetItemInfo then
        local ok, n = pcall(_G.GetItemInfo, itemID)
        if ok and n then itemName = n end
    end

    -- Sinergia con AtlasBIStooltips si tiene registrado este objeto
    if sliccNote and sliccNote.Items and sliccNote.Items[tostring(itemID)] then
        for uKey, pVal in pairs(sliccNote.Items[tostring(itemID)]) do
            local rec = sliccNote.BIS and sliccNote.BIS[uKey]
            if rec then
                local specClean = (rec.spec or ""):gsub("_P%d$", "")
                return {
                    name = itemName or ("Objeto #" .. itemID),
                    source = string.format("AtlasLoot (%s %s)", rec.class or "BiS", specClean),
                    type = "BiS Rec",
                    zone = "Classic Forever",
                    drop = "Rango " .. tostring(pVal or "1")
                }
            end
        end
    end

    return {
        name = itemName or ("Objeto #" .. itemID),
        source = "Mundo Clásico",
        type = "Kill",
        zone = "Azeroth",
        drop = "Variable"
    }
end

--- Obtiene estadísticas de avance BiS (obtenidos / total)
function ns.GetBiSProgress(classKey, bracketKey, specKey)
    classKey = classKey or select(2, UnitClass("player")) or "WARRIOR"
    local classData = ns.Data.BiS and (ns.Data.BiS[classKey] or ns.Data.BiS[classKey:upper()] or ns.Data.BiS["WARRIOR"])
    if not classData or not classData.sets then return 0, 0, 0 end

    bracketKey = bracketKey or ns.GetDefaultBiSBracket()
    local bracketSets = classData.sets[bracketKey] or classData.sets["pre-raid"] or classData.sets["15-25"]
    if not bracketSets then return 0, 0, 0 end

    local spec = specKey or (classData.specs and classData.specs[1] and classData.specs[1].key)
    local set = bracketSets[spec] or (classData.specs and classData.specs[1] and bracketSets[classData.specs[1].key])
    if not set then return 0, 0, 0 end

    local total = 0
    local acquired = 0
    for _, slotInfo in ipairs(ns.Data.BiSSlotsOrder or {}) do
        local iid = set[slotInfo.key]
        if iid and iid > 0 then
            total = total + 1
            local eq, inB = ns.GetPlayerItemStatus(iid)
            if eq or inB then
                acquired = acquired + 1
            end
        end
    end
    local pct = total > 0 and math.floor((acquired / total) * 100) or 0
    return acquired, total, pct
end
